// ui_my_saves.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

const ui_board_card = require('ui_board_card')

module.exports = ui_my_saves

async function ui_my_saves (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: inject_icons
  }

  let dricons = {}
  const { io, _ } = net(id)

  io.on = {
    up: (msg) => {
      console.log('ui_my_saves:', msg.type)
    },
    ui_board_card: card_protocol
  }

  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="board-wrapper">
      <header class="board-header">
        <h1 class="board-title">My Saved Board</h1>
        <button class="btn-create">
          <span>Create</span>
          <span class="plus-icon"></span>
        </button>
      </header>

      <nav class="board-tabs">
        <span class="tab active">Pins</span>
        <span class="tab">Forked</span>
        <span class="tab">Dataset</span>
        <span class="tab">My Components</span>
      </nav>

      <div class="card-container"></div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const plus_icon = shadow.querySelector('.plus-icon')
  const container = shadow.querySelector('.card-container')

  const subs = await sdb.watch(onbatch)

  // -----------------------------------
  // Multiple UI Cards Loop
  // -----------------------------------
  container.innerHTML = ''

  subs.forEach(async (sub) => {
    // 1. Create the wrapper div with your class name
    const slot = document.createElement('div')
    slot.className = 'card-slot'

    // 2. Initialize the card
    const card = await ui_board_card({ ...sub }, io.invite('ui_board_card', { up: id }))
    card.classList.add('ui-card-instance')

    // 3. Append the card to the slot, then slot to the container
    slot.append(card)
    container.append(slot)
  })

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(load_path_raw))
      const func = on[type] || fail
      func({ data, type })
    }
    function load_path_raw (path) { return drive.get(path).then(read_drive_file_raw) }
    function read_drive_file_raw (file) { return file.raw }
  }

  function fail ({ type, data }) { console.warn('ui_my_saves: unknown batch type', type, data) }
  function inject ({ data }) { sheet.replaceSync(data[0]) }
  function inject_icons ({ data }) {
    dricons = data
    if (plus_icon && dricons[0]) plus_icon.innerHTML = dricons[0]
  }

  function card_protocol (msg) {
    _.up(msg.type, msg.data, msg.head ? { cause: msg.head } : {})
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      ui_board_card: { $: '' },
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        ui_board_card: {
          0: '',
          1: '',
          2: '',

          mapping: {
            style: 'style',
            icons: 'icons'
            /* 
            state: 'data'
            */
          }
        },
        net_helper: {
          0: ''
        }
      },
      drive: {
        'icons/': {
          'plus.svg': { $ref: 'plus.svg' }
        },
        'style/ui_my_saves.css': {
          $ref: 'ui_my_saves.css'
        },
        /* 
        'data/': {
          'card_1.json': {
            raw: JSON.stringify({
              title: 'Mobile App Design',
              count: '12 Pins',
              has_badge: true
            })
          },
          'card_2.json': {
            raw: JSON.stringify({
              title: 'Website Templates',
              count: '8 Pins',
              has_badge: false
            })
          },
          'card_3.json': {
            raw: JSON.stringify({
              title: 'Dashboard Ideas',
              count: '24 Pins',
              has_badge: true
            })
          }
        }
        */
      }
    }
  }
}